#include "Vtb_g2x2_r_early_live_full_top.h"
#include <cstdint>
#include <cstdlib>
#include <iostream>

struct Response { bool seen=false, duplicate=false; uint8_t cfg=0, pat=0, row=0, valid=0; uint32_t address[3]={}; };
static Response canonical[4], live[4];
static void clear_log(){for(unsigned i=0;i<4;++i){canonical[i]=Response{};live[i]=Response{};}}
static void save(Response&r,uint8_t cfg,uint8_t pat,uint8_t row,uint8_t valid,const uint32_t*addr){if(r.seen){r.duplicate=true;return;}r.seen=true;r.cfg=cfg;r.pat=pat;r.row=row;r.valid=valid;for(unsigned i=0;i<3;++i)r.address[i]=addr[i];}
static void capture(Vtb_g2x2_r_early_live_full_top&d){if(d.canonical_commit_o)save(canonical[d.canonical_sa_o],d.canonical_config_o,d.canonical_pattern_o,d.canonical_is_row_o,d.canonical_line_valid_o,d.canonical_address_o);if(d.live_commit_o)save(live[d.live_sa_o],d.live_config_o,d.live_pattern_o,d.live_is_row_o,d.live_line_valid_o,d.live_address_o);}
static void tick(Vtb_g2x2_r_early_live_full_top&d){d.clk_i=0;d.eval();capture(d);d.clk_i=1;d.eval();d.clk_i=0;d.eval();}
static void reset(Vtb_g2x2_r_early_live_full_top&d){clear_log();d.rst_ni=0;d.canonical_start_i=0;d.state_update_i=0;d.test_done_valid_i=0;d.seeds_i=0;tick(d);tick(d);d.rst_ni=1;}
static bool same(){for(unsigned i=0;i<4;++i){const Response&a=canonical[i],&b=live[i];if(a.seen!=b.seen||a.duplicate||b.duplicate||a.cfg!=b.cfg||a.pat!=b.pat||a.row!=b.row||a.valid!=b.valid)return false;for(unsigned w=0;w<3;++w)if(a.address[w]!=b.address[w])return false;}return true;}
static uint32_t next(uint32_t&x){x^=x<<13;x^=x>>17;x^=x<<5;return x;}
static bool width_audit(){constexpr unsigned roles=4,actions=4,dense=3,sa=2,slot=2,cfg=3,pat=4,analyzer=5+45+65+30+7+21+7+91+1,address=65,flags=5;std::cout<<"ROLE_COUNT="<<roles<<" CONFIG_ATTEMPT_COUNT="<<actions<<" DENSE_CONFIG_COUNT="<<dense<<'\n';std::cout<<"INDEX_WIDTHS sa="<<sa<<" slot="<<slot<<" config="<<cfg<<" pattern="<<pat<<" ANALYZER_PROJECTION="<<analyzer<<'\n';std::cout<<"CONFIG_PRIORITY slots=1,0,3,2 ACTION_CONFIG=0:0,1:4,2:2,3:0\n";std::cout<<"OUTPUT_WIDTHS repairable=1 commit=1 sa=2 config=3 pattern=4 address="<<address<<" is_row="<<flags<<" line_valid="<<flags<<'\n';bool ok=roles==4&&actions==4&&dense==3&&sa==2&&slot==2&&cfg==3&&pat==4&&analyzer==272&&address==65&&flags==5;std::cout<<"HARNESS_WIDTH_AUDIT: "<<(ok?"PASS":"FAIL")<<'\n';return ok;}
int main(int ac,char**av){unsigned n=ac==2?std::strtoul(av[1],0,10):1000;if(!width_audit())return 2;uint32_t x=0x20260928;Vtb_g2x2_r_early_live_full_top d;for(unsigned v=0;v<n;++v){reset(d);d.seeds_i=next(x);d.canonical_start_i=1;tick(d);d.canonical_start_i=0;bool cd=false;for(unsigned i=0;i<24&&!cd;++i){tick(d);cd=d.canonical_done_o;}if(!cd){std::cerr<<"CANONICAL_TIMEOUT="<<v<<'\n';return 1;}for(unsigned sa_i=0;sa_i<4&&!d.live_done_o;++sa_i){bool first=(v^sa_i)&1;d.state_update_i=1;d.state_sa_i=sa_i;d.test_done_valid_i=first;d.test_done_sa_i=sa_i;tick(d);d.state_update_i=0;d.test_done_valid_i=0;for(unsigned i=0;i<8&&!d.live_done_o&&d.live_active_sa_o==sa_i;++i){if(!first&&d.live_scan_active_o){d.test_done_valid_i=1;d.test_done_sa_i=sa_i;}tick(d);d.test_done_valid_i=0;}}if(!d.live_done_o||d.canonical_repairable_o!=d.live_repairable_o||!same()){std::cerr<<"FIRST_MISMATCH="<<v<<" canonical_completed="<<unsigned(cd)<<" live_done="<<unsigned(d.live_done_o)<<'\n';return 1;}}std::cout<<"G2X2_R_EARLY_FULL_TOP_PASS vectors="<<n<<" mismatches=0 commit_response_lockstep=PASS no_duplicate_commits=PASS\n";}
